<?php

namespace App\Support\Pwa;

/** App-Symbole (Paket 43, seit 02.11.2026 Logo „Haus mit B“), als PNG eingebettet, damit kein Ordner public/ geändert werden muss. */
class Icons
{
    public const PNG = [
        192 => '',
        512 => '',
    ];

    public static function png(int $size): ?string
    {
        return isset(self::PNG[$size]) ? base64_decode(self::PNG[$size], true) : null;
    }
}
